<section aria-label="Service agent workspace"><header><h2>{{ __('Service Agent') }}</h2><p>{{ __(':count active cases', ['count' => $cases->whereNotIn('status', ['resolved', 'closed'])->count()]) }}</p></header><div class="grid gap-4 md:grid-cols-3">@foreach($cases as $case)<article wire:key="agent-case-{{ $case->id }}"><strong>{{ $case->subject }}</strong><span>{{ $case->status }}</span><small>{{ $case->classification ?? __('Unclassified') }} · {{ $case->confidence !== null ? number_format($case->confidence * 100, 0).'%' : __('No confidence') }}</small></article>@endforeach</div></section>
